/** Shape of the CLI's --output-json CreateResult. Parsed defensively. */
interface CreateResult {
  blueprint?: string;
  version?: string;
  outputDir?: string;
}

/**
 * Creates the intropy:int:create action.
 *
 * Runs `intropy int create <blueprint>` inside the scaffolder workspace to
 * generate an integration. The CLI is the single source of scaffolding logic;
 * this action just adapts it to the Backstage scaffolder (workspace-relative
 * paths, structured errors, and registered outputs).
 */
export function createIntropyIntCreateAction(options: {
  config: RootConfigService;
}) {
  const { config } = options;

  return createTemplateAction({
    id: 'intropy:int:create',
    description:
      'Scaffolds an integration by running the intropy CLI (int create) against a blueprint.',
    examples: intropyIntCreateExamples,
    schema: {
      input: {
        blueprint: z => z.string().describe('Blueprint id, e.g. hello-world'),
        name: z => z.string().describe('Name of the integration to create'),
        targetPath: z =>
          z
            .string()
            .optional()
            .describe(
              'Workspace-relative directory to generate into. Defaults to the workspace root.',
            ),
        values: z =>
          z
            .record(z.any())
            .optional()
            .describe('Blueprint parameter values (may be nested).'),
      },
      output: {
        outputDir: z =>
          z
            .string()
            .describe('Workspace-relative path of the generated integration.'),
        blueprintVersion: z =>
          z.string().describe('Resolved blueprint version.'),
        blueprint: z => z.string().describe('Resolved blueprint id.'),
      },
    },
    async handler(ctx) {
      const { blueprint, name, targetPath, values } = ctx.input;

      const outDir = resolveSafeChildPath(ctx.workspacePath, targetPath ?? '.');
      await fs.ensureDir(outDir);

      // Values and the result file go in an auto-cleaned temp dir so they never
      // land in the published workspace.
      const tmpDir = await ctx.createTemporaryDirectory();
      const resultPath = path.join(tmpDir, 'result.json');

      const args = [
        'int',
        'create',
        blueprint,
        '--output',
        outDir,
        '--name',
        name,
        '--no-input',
        '--skip-install-skills',
        '--output-json',
        resultPath,
      ];

      // JSON is a strict subset of YAML, so the CLI's -f parser accepts it and
      // we avoid --set string-flattening of nested values.
      if (values && Object.keys(values).length > 0) {
        const valuesPath = path.join(tmpDir, 'values.json');
        await fs.writeFile(valuesPath, JSON.stringify(values, null, 2), 'utf8');
        args.push('-f', valuesPath);
      }

      const cliPath = config.getOptionalString('intropy.cli.path') ?? 'intropy';

      ctx.logger.info(
        `Running intropy int create ${blueprint} (name: ${name})`,
      );

      const { exitCode, stderrTail } = await runIntropyCli({
        command: cliPath,
        args,
        cwd: ctx.workspacePath,
        env: { ...process.env },
        logger: ctx.logger,
      });

      if (exitCode === 2) {
        throw new InputError(
          `intropy rejected the input for blueprint '${blueprint}' (usage error). ` +
            `Check that all required blueprint parameters are provided.\n${stderrTail.join(
              '\n',
            )}`,
        );
      }
      if (exitCode !== 0) {
        throw new Error(
          `intropy int create failed (exit ${exitCode}).\n${stderrTail.join(
            '\n',
          )}`,
        );
      }

      let result: CreateResult = {};
      try {
        result = JSON.parse(await fs.readFile(resultPath, 'utf8'));
      } catch (err) {
        ctx.logger.warn(
          `intropy succeeded but its --output-json result could not be read: ${err}`,
        );
      }

      // The CLI reports an absolute outputDir; downstream steps (fs, publish)
      // need it relative to the workspace. Fall back to the requested outDir.
      const absOutputDir = result.outputDir ?? outDir;
      const relOutputDir = path.relative(ctx.workspacePath, absOutputDir);
      if (relOutputDir.startsWith('..') || path.isAbsolute(relOutputDir)) {
        throw new Error(
          `intropy wrote outside the workspace (${absOutputDir}); refusing to continue.`,
        );
      }

      ctx.output('outputDir', relOutputDir);
      ctx.output('blueprintVersion', result.version ?? 'unknown');
      ctx.output('blueprint', result.blueprint ?? blueprint);

      ctx.logger.info(
        `Created ${result.blueprint ?? blueprint}@${
          result.version ?? 'unknown'
        } at ${relOutputDir}`,
      );
    },
  });
}

